pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: the address to set as new owner. The general rule:
    // If the caller is the admin, calling setOwner(addr) sets c.owner() == addr.
    // The mutant that omits assignment will fail this for some addr.
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid zero-address ambiguity if desired
        // (zero address is admissible in the original contract, so do not exclude it)

        // The deployer (this contract) is the admin because c was created in setUp()
        // We must call as that admin. Use vm.prank to ensure msg.sender == admin.
        vm.prank(address(this));

        bool ok;
        // call setOwner as admin; capture whether it returned/filled without revert
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // Single universal assertion: after a successful call by the admin, the public getter owner()
        // equals the provided newOwner. The reference contract always satisfies this for any newOwner;
        // the mutant that omits the assignment will leave owner unchanged for some inputs and thus fail.
        // We only assert the relationship; if setOwner reverted/returned false, the property may not hold,
        // but reference returns true and sets owner for all inputs, so this assert will pass on reference
        // and fail on the mutant for some fuzzed newOwner values.
        assertTrue(c.owner() == newOwner);
    }
}

