pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: an arbitrary address chosen by the fuzzer which will act as tx.origin,
    // and an arbitrary address as the _owner argument passed through a forwarder.
    function testFuzz_property(address originator, address desiredOwner) public {
        // Avoid the zero address for clarity, but keep domain wide
        if (originator == address(0)) originator = address(1);
        if (desiredOwner == address(0)) desiredOwner = address(2);

        // Deploy a simple forwarder that will call c.setOwner(desiredOwner) on behalf of its caller.
        // The reference contract's onlyAdmin modifier requires msg.sender == admin (the deployer of c).
        // In setUp, c was deployed by this test contract, so this contract is admin. We need the
        // forwarder to invoke c.setOwner while msg.sender == address(forwarder) and tx.origin == originator.
        Forwarder f = new Forwarder();

        // We must make the tx.origin equal to originator. To do that, have the fuzzer-provided
        // originator address be an EOA that initiates the transaction: use vm.prank(originator) so
        // the simulated tx.origin/prank is the desired originator and msg.sender inside the call
        // from originator to forwarder will be originator; the forwarder will then call c, making
        // tx.origin == originator and msg.sender == address(forwarder).

        // Ensure this test contract is the admin expected by c: setUp deployed c from this test, so admin==address(this).
        // We need the forwarder to have this test contract call through it as admin. To have msg.sender==admin when
        // calling setOwner on c, the forwarder must call c.setOwner while the forwarder is invoked by admin.
        // So do: vm.prank(address(this)) call forwarder which will then call c. But to create tx.origin != admin we
        // must have the top-level tx originated by originator. Achieve by having originator call the forwarder, and the forwarder
        // will perform a low-level call that impersonates admin by using delegatecall? That is not necessary: the onlyAdmin
        // check requires msg.sender == admin, so the immediate caller must be admin (address(this)). Thus admin must be the forwarder.
        // Simpler approach: we will have this test contract (admin) call the forwarder, but the fuzzer controls originator by
        // making the EOA that started the transaction equal to originator via vm.prank. That yields tx.origin == originator,
        // msg.sender == address(this) when calling forwarder, and inside forwarder when it calls c, msg.sender == forwarder,
        // which will fail the onlyAdmin check. To satisfy onlyAdmin, the caller of c.setOwner must be admin (this test), so the
        // forwarder must call c in a way that makes msg.sender == this test contract. The forwarder cannot make msg.sender equal to
        // this test contract unless this test contract calls c directly. Therefore the correct way: the admin (this test) will call
        // c.setOwner through a separate helper that forwards but preserves msg.sender as the original caller by using a call to c
        // from the helper via address(this).call? That's impossible. To manifest tx.origin difference we instead have admin be the forwarder
        // itself: deploy the contract c with admin being the forwarder. But setUp already deployed c. To preserve setUp requirement, we can
        // instead have this test (admin) call setOwner on c while tx.origin is originator by using vm.prank(originator, address(this)).
        // Foundry's vm.prank(addr) sets msg.sender for the next call; vm.prank(txOrigin, msgSender) sets both tx.origin and msg.sender.
        // Use vm.prank(originator, address(this)) so that the top-level tx origin is originator but msg.sender is this test contract (admin).

        // Now, when this test (admin) calls c.setOwner(desiredOwner) under vm.prank(originator, address(this)),
        // in the reference contract owner should be set to desiredOwner. The mutant sets owner to tx.origin (originator),
        // so for many inputs desiredOwner != originator, causing the mutant to differ.

        vm.prank(originator, address(this));
        bool ok;
        try c.setOwner(desiredOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        // Exactly one assertion: in the correct contract, after the call, owner() equals the provided desiredOwner for ALL inputs
        // (because onlyAdmin passes and setOwner assigns the parameter). The mutant will set owner() == tx.origin (originator)
        // for some inputs (when desiredOwner != originator), causing this assertion to fail.
        assertTrue(ok && c.owner() == desiredOwner);
    }
}

