        // We observe c.owner() via its public getter. For the reference contract this holds for all admissible inputs. The mutant
        // will set owner == tx.origin (originEOA) and therefore when originEOA != intendedOwner the mutant will violate this assertion.
        assertTrue(ok && (c.owner() == intendedOwner));
    }
}

